from langflow.custom import Component
from langflow.io import HandleInput, Output
from langflow.schema.message import Message


class CustomComponent(Component):
    display_name = "Tavily News Cleaner"
    description = "Normalise raw Tavily results into clean, delimited article blocks for extraction."
    icon = "filter"
    name = "TavilyNewsCleaner"

    MAX_CHARS = 1500

    inputs = [
        HandleInput(
            name="results",
            display_name="Tavily Results",
            input_types=["DataFrame", "Data", "Table"],
            info="Raw search results from the Tavily Search component.",
        ),
    ]
    outputs = [
        Output(display_name="Clean Text", name="clean_text", method="build_text"),
    ]

    def _records(self) -> list:
        data = self.results
        if data is None:
            return []
        if hasattr(data, "to_dict"):
            try:
                return data.to_dict(orient="records")
            except Exception:  # noqa: BLE001
                pass
        if isinstance(data, list):
            return [getattr(x, "data", x) for x in data]
        inner = getattr(data, "data", None)
        if isinstance(inner, list):
            return [getattr(x, "data", x) for x in inner]
        if isinstance(inner, dict):
            return [inner]
        return []

    @staticmethod
    def _clean(value) -> str:
        return value.strip() if isinstance(value, str) else ""

    def build_text(self) -> Message:
        blocks: list[str] = []
        seen: set[str] = set()
        for record in self._records():
            if not isinstance(record, dict):
                continue
            title = self._clean(record.get("title"))
            url = self._clean(record.get("url"))
            content = self._clean(record.get("content"))
            if not title or not url or not content:
                continue
            if url in seen:  # drop duplicate sources within a run
                continue
            seen.add(url)
            blocks.append(f"TITLE: {title}\nURL: {url}\nCONTENT: {content[: self.MAX_CHARS]}")

        text = "\n\n---\n\n".join(blocks) or "NO_ARTICLES_FOUND"
        self.status = f"{len(blocks)} article(s) cleaned"
        return Message(text=text)

from datetime import datetime, timezone

from langflow.custom import Component
from langflow.io import DataInput, Output
from langflow.schema import Data


class CustomComponent(Component):
    display_name = "News Expander"
    description = "Flatten structured news rows into Astra documents (one embeddable doc per article)."
    icon = "code"
    name = "NewsExpander"

    FIELDS = [
        "title", "source", "publication_date", "importance", "sentiment",
        "key_observations", "url", "ticker", "description", "event",
    ]

    inputs = [
        DataInput(name="data", display_name="Structured Rows", info="Structured output from the extractor."),
    ]
    outputs = [
        Output(display_name="Documents", name="output", method="build_output"),
    ]

    def _rows(self) -> list:
        raw = self.data
        rows = getattr(raw, "results", raw)
        if isinstance(rows, dict):
            rows = [rows]
        if not isinstance(rows, list):
            rows = [rows]
        return rows

    @staticmethod
    def _norm_sentiment(value) -> str:
        v = (value or "").strip().lower() if isinstance(value, str) else ""
        if v.startswith("pos"):
            return "Positive"
        if v.startswith("neg"):
            return "Negative"
        return "Neutral"

    @staticmethod
    def _norm_importance(value) -> str:
        v = (value or "").strip().lower() if isinstance(value, str) else ""
        if v.startswith("h"):
            return "High"
        if v.startswith("l"):
            return "Low"
        return "Medium"

    def build_output(self) -> list[Data]:
        ingested_at = datetime.now(timezone.utc).isoformat()
        docs: list[Data] = []
        for row in self._rows():
            record = getattr(row, "data", row)
            if not isinstance(record, dict):
                continue
            # Astra rejects empty content ("empty Part"): require a non-empty body.
            page_content = (record.get("description") or record.get("title") or "").strip()
            if not page_content:
                continue
            doc = {"page_content": page_content, "text": page_content}
            for key in self.FIELDS:
                doc[key] = record.get(key, "")
            # UI sentiment math + significance dot depend on capitalised, bounded
            # enums — normalise defensively so a sloppy LLM answer can't break them.
            doc["sentiment"] = self._norm_sentiment(doc.get("sentiment"))
            doc["importance"] = self._norm_importance(doc.get("importance"))
            doc["ingested_at"] = ingested_at
            docs.append(Data(data=doc))
        self.status = f"{len(docs)} document(s) ready for Astra"
        return docs
